insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.418.d.1',3,'An architect''s client asks her to skip a required sprinkler system to cut costs. The ethical course is to:','["explain the code requirement and keep the system", "omit it quietly", "let the contractor decide", "hide it from inspectors"]'::jsonb,0,'Life-safety codes protect occupants.','original'),
('127.418.d.1',4,'A building designer notices that his firm''s published project photos show features the firm did not design. Ethics requires him to:','["delete the real drawings", "correct the credit", "stay silent", "add more false photos"]'::jsonb,1,'Honest representation of work is an ethical duty.','original'),
('127.418.d.2.A',3,'A firm designing a school library begins by writing a clear statement of what the library must do. That is the first stage of the:','["weather cycle", "election cycle", "design process", "tax cycle"]'::jsonb,2,'Design starts with defining the problem.','original'),
('127.418.d.2.A',4,'After a mock-up of a stair shows the rise is too steep, the team revises the plans and builds a second mock-up. This repetition is called:','["delegation", "inflation", "abandonment", "iteration"]'::jsonb,3,'Iteration refines the design.','original'),
('127.418.d.2.B',3,'A client wants a 20-story tower on a lot that zoning limits to four stories. This conflict is a limit on the project''s:','["scope", "mascot", "slogan", "parking color"]'::jsonb,0,'Regulation limits what is possible.','original'),
('127.418.d.2.B',4,'Selecting a cheaper insulation that fails the energy code is an ethical problem because it risks occupant:','["decor", "safety and compliance", "menu", "parking"]'::jsonb,1,'Ethics weighs more than savings.','original'),
('127.418.d.2.C',3,'Neighbors of a proposed apartment building are stakeholders because the building will change their street''s:','["recipes", "playlists", "traffic and views", "tax forms"]'::jsonb,2,'Stakeholders include those affected.','original'),
('127.418.d.2.C',4,'A fire marshal who reviews a hotel design is a stakeholder whose main concern is:','["lobby music", "staff uniforms", "interior color", "life safety"]'::jsonb,3,'Different stakeholders have different priorities.','original'),
('127.418.d.2.D',3,'A scale model of a roof is loaded until it deflects too far. The failure is helpful because it shows what to strengthen before:','["full-size construction", "a sale", "a vacation", "a party"]'::jsonb,0,'Test failure improves the design.','original'),
('127.418.d.2.D',4,'Studies of the Hyatt Regency walkway collapse led engineers to improve how they review:','["carpet samples", "connection details", "paint colors", "furniture styles"]'::jsonb,1,'Failure analysis changes practice.','original'),
('127.418.d.4.A',3,'The part of a building that transfers its weight to the ground is the:','["awning", "chimney cap", "foundation", "canopy"]'::jsonb,2,'Foundations support the structure.','original'),
('127.418.d.4.A',4,'Walls, floors, roof, and foundation are all fundamental parts of a:','["traffic signal", "landscape plan", "bridge cable", "building"]'::jsonb,3,'These are the basic building elements.','original'),
('127.418.d.4.B',3,'Repeating windows in a regular pattern along a facade is an example of the visual design element of:','["rhythm", "friction", "gravity", "inertia"]'::jsonb,0,'Repetition creates rhythm.','original'),
('127.418.d.4.B',4,'A building that places a tall entrance tower at one end of a long low wing uses the design principle of:','["erosion", "emphasis", "depreciation", "corrosion"]'::jsonb,1,'A focal point draws attention.','original'),
('127.418.d.4.C',3,'Early settlers built homes from local materials such as logs and sod, showing that building styles often reflect available:','["coupons", "lyrics", "resources", "trophies"]'::jsonb,2,'Location shapes construction.','original'),
('127.418.d.4.C',4,'The invention of the elevator and steel frames made it possible to build the first:','["castles", "pyramids", "aqueducts", "skyscrapers"]'::jsonb,3,'Technology changed building height.','original'),
('127.418.d.5.A',3,'Wood, masonry, steel, and concrete are common building:','["materials", "hobbies", "languages", "moods"]'::jsonb,0,'These are structural materials.','original'),
('127.418.d.5.A',4,'A material made of fired clay blocks laid with mortar is called:','["vinyl siding", "brick masonry", "steel plate", "glass curtain"]'::jsonb,1,'Brick is a masonry unit.','original'),
('127.418.d.5.B',3,'Asphalt shingles, clay tiles, and metal panels are all common types of:','["flooring", "wiring", "roofing", "plumbing"]'::jsonb,2,'Roofing keeps weather out.','original'),
('127.418.d.5.B',4,'A roofing material that is very long lasting and sheds snow easily is:','["thatch", "newspaper", "cardboard", "standing seam metal"]'::jsonb,3,'Metal roofs are durable.','original'),
('127.418.d.5.C',3,'Building a house by nailing studs into a frame and then covering it with sheathing is called:','["wood framing", "post-tensioning", "tilt-wall", "slip forming"]'::jsonb,0,'Light-frame wood is traditional in houses.','original'),
('127.418.d.5.C',4,'Tilt-wall construction forms large concrete wall panels flat on the ground and then:','["paints them first", "lifts them upright with a crane", "freezes them", "floats them downstream"]'::jsonb,1,'Panels are tilted into place.','original'),
('127.418.d.5.D',3,'Building sections in a factory and shipping them to the site is called prefabricated or:','["land clearing", "demolition", "modular construction", "hand digging"]'::jsonb,2,'Factory construction speeds work.','original'),
('127.418.d.5.D',4,'Modular construction can reduce weather delays because most of the work is done:','["in the rain", "on the roof", "at night only", "indoors in a factory"]'::jsonb,3,'Controlled conditions speed work.','original'),
('127.418.d.5.E',3,'Standard building methods include casting concrete, cutting lumber, and:','["joining materials with fasteners", "freezing steel", "painting the sky", "growing bricks"]'::jsonb,0,'Basic methods shape raw materials.','original'),
('127.418.d.5.E',4,'Pouring liquid concrete into a form so it hardens into the desired shape is called:','["sanding", "casting", "tearing", "slicing"]'::jsonb,1,'Casting makes shapes by pouring.','original'),
('127.418.d.5.F',3,'A building in a hurricane zone may use impact-resistant windows because resilient materials help it survive:','["commercials", "holidays", "severe storms", "parties"]'::jsonb,2,'Resilience reduces damage.','original'),
('127.418.d.5.F',4,'Resilient materials often cost more at first, but they can save money by reducing repair costs after a:','["birthday", "game", "concert", "disaster"]'::jsonb,3,'Life-cycle thinking supports resilience.','original'),
('127.418.d.5.G',3,'A designer who must meet a green building rating may choose materials with recycled content because the rating rewards:','["sustainability", "popularity", "height", "decoration"]'::jsonb,0,'Certifications influence material choices.','original'),
('127.418.d.5.G',4,'The local climate affects material selection because heavy rain, heat, and snow each:','["raise the sun", "wear materials differently", "hide the foundation", "change the zip code"]'::jsonb,1,'Climate drives durability needs.','original'),
('127.418.d.6.A',3,'A local building code exists mainly to protect public health and:','["parking", "profit", "safety", "fashion"]'::jsonb,2,'Codes protect people.','original'),
('127.418.d.6.A',4,'Requiring smoke alarms in every bedroom is a building code that protects occupants from:','["pollen", "noise", "traffic", "fire"]'::jsonb,3,'Codes address specific hazards.','original'),
('127.418.d.6.B',3,'Land use regulations divide a city into districts such as residential, commercial, and:','["industrial", "edible", "musical", "fictional"]'::jsonb,0,'Zoning separates uses.','original'),
('127.418.d.6.B',4,'A zoning ordinance allows a corner store in a commercial district but not in a district zoned strictly:','["retail", "single-family residential", "downtown mixed", "industrial heavy"]'::jsonb,1,'Allowable uses vary by district.','original'),
('127.418.d.6.C',3,'Zoning controls land use and development by setting limits on building height, setbacks, and:','["tenant names", "color of the sky", "density", "music"]'::jsonb,2,'Zoning shapes growth.','original'),
('127.418.d.6.C',4,'A required front setback of 25 feet means a building must be placed at least 25 feet from the:','["power meter", "neighbor''s roof", "back door", "front property line"]'::jsonb,3,'Setbacks are measured from property lines.','original'),
('127.418.d.6.D',3,'Ramps, elevators, and wide doorways are standard features that make a building accessible to people with:','["disabilities", "tools only", "cameras", "pets only"]'::jsonb,0,'Accessibility features support all users.','original'),
('127.418.d.6.D',4,'An accessible parking space is located near the entrance so a person who uses a wheelchair can travel a shorter:','["color", "distance", "mood", "tax"]'::jsonb,1,'Closer spaces reduce travel.','original'),
('127.418.d.6.E',3,'Fire codes limit how far a person must travel to reach an exit, which constrains a building''s:','["mascot", "paint colors", "floor plan layout", "insurance form"]'::jsonb,2,'Egress rules shape plans.','original'),
('127.418.d.6.E',4,'A code that limits the height of a combustible building to a few stories constrains a designer''s choice of:','["wallpaper", "phone system", "carpet color", "construction type"]'::jsonb,3,'Codes limit what types may be used.','original'),
('127.418.d.6.F',3,'Energy codes require minimum insulation, which constrains the design of a building''s:','["walls and roof", "menu", "fonts", "parking stripes"]'::jsonb,0,'Energy rules shape envelope design.','original'),
('127.418.d.6.F',4,'A building envelope that fails the energy code can be sent back for redesign before the owner receives a:','["gift", "certificate of occupancy", "holiday card", "trophy"]'::jsonb,1,'Code review precedes occupancy.','original'),
('127.418.d.6.G',3,'A building used for sleeping, such as an apartment, is classified by its occupancy as:','["assembly", "industrial", "residential", "storage"]'::jsonb,2,'Occupancy describes use.','original'),
('127.418.d.6.G',4,'A building''s use type, occupancy, and construction type together determine which code requirements apply, such as the number of required:','["trees", "windows only", "colors", "exits"]'::jsonb,3,'Classification drives rules.','original'),
('127.418.d.7.A',3,'Tilt-wall panels, glass curtain walls, and brick veneer are different types of building:','["envelopes", "foundations", "elevators", "signs"]'::jsonb,0,'The envelope is the exterior shell.','original'),
('127.418.d.7.A',4,'The building envelope separates the conditioned interior from the exterior, so it controls heat, air, and:','["tenants", "moisture", "traffic", "music"]'::jsonb,1,'The envelope is a barrier.','original'),
('127.418.d.7.B',3,'The foundation, walls, windows, and roof are all components of the building:','["directory", "signage", "envelope", "elevator"]'::jsonb,2,'These form the shell.','original'),
('127.418.d.7.B',4,'A roof that leaks in a heavy rain has failed in its role as part of the building''s:','["stair system", "fire alarm", "parking plan", "water barrier"]'::jsonb,3,'The roof sheds water.','original'),
('127.418.d.7.C',3,'Fiberglass batts, spray foam, and rigid board are all types of:','["insulation", "lighting", "paint", "flooring"]'::jsonb,0,'Insulation slows heat flow.','original'),
('127.418.d.7.C',4,'Insulation is rated by R-value, and a higher R-value means the material is better at resisting:','["color change", "heat flow", "noise only", "moisture only"]'::jsonb,1,'R-value measures thermal resistance.','original'),
('127.418.d.7.D',3,'Double-hung, casement, and sliding styles describe different types of building:','["footings", "roofs", "windows", "slabs"]'::jsonb,2,'Window types differ in operation.','original'),
('127.418.d.7.D',4,'Low-E coatings on glass help reduce heat transfer, so they are used on energy-efficient:','["floors", "chimneys", "driveways", "windows"]'::jsonb,3,'Coatings reduce heat flow.','original'),
('127.418.d.7.E',3,'The heating, ventilation, and air conditioning system, or HVAC, controls a building''s indoor:','["temperature and air quality", "property taxes", "street names", "wall colors"]'::jsonb,0,'HVAC conditions air.','original'),
('127.418.d.7.E',4,'Ductwork in an HVAC system carries conditioned air from the equipment to the:','["foundation", "rooms", "street", "attic fire"]'::jsonb,1,'Ducts deliver air.','original'),
('127.418.d.7.F',3,'A building that earns a LEED rating has been recognized for meeting standards of green:','["age", "size", "performance", "height"]'::jsonb,2,'LEED rates sustainability.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.418.d.7.F',4,'Pursuing a LEED certification can influence the choice of mechanical equipment because efficient systems earn:','["fines", "complaints", "delays", "rating credits"]'::jsonb,3,'Credits reward efficiency.','original'),
('127.418.d.7.G',3,'An electrical system brings power from the utility through a service panel and then through branch circuits to outlets and:','["lights", "windows", "pipes", "ducts"]'::jsonb,0,'Circuits deliver power.','original'),
('127.418.d.7.G',4,'A circuit breaker in the panel protects a circuit from overload by:','["lowering the voltage", "shutting off the current", "painting the wire", "adding more current"]'::jsonb,1,'Breakers trip to prevent overheating.','original'),
('127.418.d.7.H',3,'A plumbing system includes supply pipes that bring in clean water and drain pipes that carry away:','["electricity", "heat", "wastewater", "light"]'::jsonb,2,'Plumbing moves water.','original'),
('127.418.d.7.H',4,'Drain pipes use traps, like the curved pipe under a sink, to block sewer gas from entering the:','["street", "garage door", "yard", "building"]'::jsonb,3,'Traps hold a water seal.','original'),
('127.418.d.8.A',3,'A house on weak soil is often placed on a slab with thickened edges or on piers. Both are examples of building:','["foundation types", "roofing types", "window types", "siding types"]'::jsonb,0,'Foundation type fits soil and load.','original'),
('127.418.d.8.A',4,'A basement foundation extends well below grade, which makes it well suited where the frost line lies:','["near the surface", "far down in the ground", "irrelevant", "absent"]'::jsonb,1,'Footings must go below the frost depth.','original'),
('127.418.d.8.B',3,'A lab sorts a soil by grain size using stacked screens called:','["magnets", "mirrors", "sieves", "scales"]'::jsonb,2,'Sieve analysis classifies grains.','original'),
('127.418.d.8.B',4,'A soil that is mostly very fine grains and shows plastic behavior when wet is probably a:','["boulder", "cobble", "gravel", "clay"]'::jsonb,3,'Fines and plasticity indicate clay.','original'),
('127.418.d.8.C',3,'A soil sample has a liquid limit of 52 and a plastic limit of 22. Its plasticity index is:','["30", "52", "74", "22"]'::jsonb,0,'52 - 22 = 30.','original'),
('127.418.d.8.C',4,'The plasticity index tells an engineer the range of moisture over which a soil behaves as a:','["rigid gas", "plastic material", "solid ice", "pure sand"]'::jsonb,1,'PI measures the plastic range.','original'),
('127.418.d.8.D',3,'A soil with a sieve analysis showing mostly sand and a trace of fines would receive a USCS symbol beginning with:','["X", "Q", "S", "Z"]'::jsonb,2,'S stands for sand.','original'),
('127.418.d.8.D',4,'In the USCS, the group symbol CH describes a clay with:','["no plasticity", "coarse grains", "organic matter", "high plasticity"]'::jsonb,3,'CH = fat clay.','original'),
('127.418.d.8.E',3,'A force that pulls a member apart is called:','["tension", "bearing", "compression", "shear"]'::jsonb,0,'Tension stretches.','original'),
('127.418.d.8.E',4,'A force that tends to slide one part of a member past an adjacent part is:','["compression", "shear", "buoyancy", "tension"]'::jsonb,1,'Shear slides layers.','original'),
('127.418.d.8.F',3,'Wind pushing on a wall and snow resting on a roof are both examples of environmental:','["hobbies", "fonts", "loads", "projects"]'::jsonb,2,'Environmental loads act on buildings.','original'),
('127.418.d.8.F',4,'Furniture and occupants are counted as live load, while the weight of the finished floor itself is counted as:','["seismic load", "live load", "wind load", "dead load"]'::jsonb,3,'Permanent weight is dead load.','original'),
('127.418.d.8.G',3,'A diagram that shows a load on a beam passing through the beam to its supports illustrates a load:','["path", "menu", "story", "rumor"]'::jsonb,0,'Load paths trace forces.','original'),
('127.418.d.8.G',4,'A roof load is carried by rafters, then walls, then the foundation. If a wall were removed, the load would have no way to reach the:','["attic", "ground", "porch", "sky"]'::jsonb,1,'The load path must be continuous.','original'),
('127.418.d.8.H',3,'A simply supported beam 8 m long carries a single 40 kN load at midspan. The reaction at each support is:','["80 kN", "10 kN", "20 kN", "40 kN"]'::jsonb,2,'Half of the load goes to each support.','original'),
('127.418.d.8.H',4,'A beam of length 6 m has a 12 kN point load 2 m from the left support. The right reaction is:','["8 kN", "12 kN", "6 kN", "4 kN"]'::jsonb,3,'Moment about left: R x 6 = 12 x 2 so R = 4 kN.','original'),
('127.418.d.8.I',3,'On a shear and moment diagram, the maximum moment occurs where the shear force crosses:','["zero", "the left support", "infinity", "its maximum"]'::jsonb,0,'Moment peaks where shear is zero.','original'),
('127.418.d.8.I',4,'A simply supported beam of span 2 m with a 20 kN midspan load has a maximum moment of:','["5 kN-m", "10 kN-m", "80 kN-m", "40 kN-m"]'::jsonb,1,'M = PL/4 = 10 x 4 / 4 = 10.','original'),
('127.418.d.8.J',3,'A Pratt truss, a Howe truss, and a Warren truss are all types of:','["doors", "footings", "trusses", "slabs"]'::jsonb,2,'These are common truss configurations.','original'),
('127.418.d.8.J',4,'A truss whose members all lie in the same flat plane, such as a typical roof truss, is classified as:','["rotational", "helical", "spherical", "planar"]'::jsonb,3,'Planar trusses are two-dimensional.','original'),
('127.418.d.8.K',3,'To find the support reactions of a roof truss under a load, the designer begins with a diagram of the truss showing the loads and:','["supports", "colors", "leaves", "prices"]'::jsonb,0,'Reactions are found from supports.','original'),
('127.418.d.8.K',4,'A truss is supported by a pin at one end and a roller at the other. The roller can provide only a:','["no reaction", "vertical reaction", "moment reaction", "horizontal and vertical reaction"]'::jsonb,1,'A roller resists perpendicular to the surface.','original'),
('127.418.d.8.L',3,'The minimum snow load for a roof in a given city is set by the building code so every designer uses the same:','["opinion", "rumor", "standard", "guess"]'::jsonb,2,'Codes define design loads.','original'),
('127.418.d.8.L',4,'Design loads are set by code rather than chosen by each designer because consistent minimums protect:','["the paint supplier", "a single firm", "the designer''s fee", "the public"]'::jsonb,3,'Consistency protects safety.','original'),
('127.418.d.8.M',3,'Concrete is made from cement, water, sand, and:','["coarse aggregate", "sawdust", "salt", "sugar"]'::jsonb,0,'Aggregate gives bulk and strength.','original'),
('127.418.d.8.M',4,'A mix with a lower water-cement ratio generally produces concrete that is:','["lighter in color", "stronger", "weaker", "more watery"]'::jsonb,1,'Less water gives higher strength.','original'),
('127.418.d.8.N',3,'An admixture added to help concrete resist freeze-thaw damage is called an:','["sand reducer", "dye remover", "air-entraining agent", "rust agent"]'::jsonb,2,'Air bubbles relieve pressure.','original'),
('127.418.d.8.N',4,'A water-reducing admixture lets a contractor keep concrete workable while using:','["hot paint", "more cement dust", "colored sand", "less water"]'::jsonb,3,'It improves strength without extra water.','original'),
('127.418.d.8.O',3,'On a hot summer day, a contractor may add a retarder to slow the concrete''s:','["setting time", "color", "density", "price"]'::jsonb,0,'Retarders slow hardening in heat.','original'),
('127.418.d.8.O',4,'In cold weather, an accelerator is chosen so the concrete gains strength before it can be damaged by:','["mud", "freezing", "wind sound", "rain gear"]'::jsonb,1,'Accelerators speed strength gain.','original'),
('127.418.d.8.P',3,'A concrete cylinder is crushed in a machine to measure its:','["age", "color", "compressive strength", "smell"]'::jsonb,2,'Compression tests measure strength.','original'),
('127.418.d.8.P',4,'The splitting tension test is used because concrete is much weaker in tension than in:','["shear only", "heat", "torsion only", "compression"]'::jsonb,3,'Tensile strength is low.','original'),
('127.418.d.8.Q',3,'A slump test measures how much a cone of fresh concrete sinks, which shows its:','["workability", "age", "strength after a year", "color"]'::jsonb,0,'Slump reflects consistency.','original'),
('127.418.d.8.Q',4,'A slump that is much higher than specified suggests that the concrete mix has too much:','["sand", "water", "cement bags", "rock"]'::jsonb,1,'High slump means a wetter mix.','original'),
('127.418.d.9.A',3,'A stormwater system for a building collects rain from the roof, channels it through downspouts, and carries it to a:','["elevator", "bedroom", "drain or detention area", "kitchen"]'::jsonb,2,'Roof drains collect runoff.','original'),
('127.418.d.9.A',4,'Sloping a parking lot toward an inlet is part of a stormwater system that keeps water from:','["raising insurance", "adding trees", "improving traffic", "ponding near the building"]'::jsonb,3,'Slope moves water away.','original'),
('127.418.d.9.B',3,'Designing ingress and egress means planning how people enter and:','["exit safely", "cook", "vote", "sleep"]'::jsonb,0,'Egress gets people out.','original'),
('127.418.d.9.B',4,'Building codes require exits to be marked and to swing in the direction of travel for large rooms so crowds can:','["stay seated", "evacuate quickly", "find food", "arrive late"]'::jsonb,1,'Egress rules improve safety.','original'),
('127.418.d.9.C',3,'A designer adds extra wall insulation and efficient windows to meet an energy goal. This lowers the building''s use of:','["paint", "paper", "heating and cooling energy", "parking"]'::jsonb,2,'Efficient envelopes cut energy.','original'),
('127.418.d.9.C',4,'Orienting a building so long walls face north and south and adding overhangs is a passive method of reducing:','["site area", "structure weight", "code review", "cooling loads"]'::jsonb,3,'Passive design saves energy.','original'),
('127.418.d.9.D',3,'When a geotechnical report shows weak surface soil, the designer may recommend and defend a deep foundation such as:','["drilled piers", "window frames", "roof tiles", "carpet tiles"]'::jsonb,0,'Deep foundations reach strong soil.','original'),
('127.418.d.9.D',4,'A recommended foundation should be defended with soil data, building loads, and:','["wall paint", "cost and constructability", "sign design", "office layout"]'::jsonb,1,'Choices are justified by data.','original'),
('127.418.d.9.E',3,'Software that lets a designer model a building as a 3D object and view it from any angle is called:','["a word processor", "a calendar", "3D modeling software", "a spreadsheet"]'::jsonb,2,'3D tools aid visualization.','original'),
('127.418.d.9.E',4,'Making a change in one part of a 3D model that updates all related views reduces the chance of:','["building anything", "having a design", "using a computer", "drawing conflicts"]'::jsonb,3,'Models keep views consistent.','original'),
('127.418.d.9.F',3,'CAD software lets a designer draw plans with precise lengths and angles, using commands for lines, arcs, and:','["dimensions", "emojis", "songs", "games"]'::jsonb,0,'CAD produces accurate drawings.','original'),
('127.418.d.9.F',4,'Layers in a CAD drawing separate items such as walls, dimensions, and text so they can be shown or:','["eaten", "hidden", "burned", "spoken"]'::jsonb,1,'Layers organize information.','original'),
('127.418.d.9.G',3,'A rendering that shows a building from a corner, with depth and perspective, is a three-dimensional:','["menu", "timesheet", "view", "budget"]'::jsonb,2,'3D views show form.','original'),
('127.418.d.9.G',4,'Presenting a 3D view to a client helps them understand the design before it is:','["photographed by satellites", "named", "taxed", "built"]'::jsonb,3,'Visuals support communication.','original'),
('127.418.d.9.H',3,'A solid model of a building represents walls and slabs as objects with thickness, unlike a wireframe that shows only:','["edges", "walls", "colors", "windows"]'::jsonb,0,'Wireframes show edges only.','original'),
('127.418.d.9.H',4,'Because a solid model contains volume, the software can extract quantities such as:','["the tenant''s name", "the volume of concrete", "the color of paint chosen", "the weather forecast"]'::jsonb,1,'Solid models give quantities.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
