select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.418.d.9.I',3,'After finishing a building design, the team presents it to a panel that gives feedback in a design:','["audit", "raffle", "critique", "lottery"]'::jsonb,2,'Critiques improve work.','original'),
('127.418.d.9.I',4,'When receiving critique on a building design, a designer should listen carefully and decide which comments to apply to the:','["kitchen menu", "client''s lunch", "parking sign", "next revision"]'::jsonb,3,'Feedback guides revision.','original'),
('127.418.d.9.J',3,'Preliminary drawings are early sketches of a structure used to test ideas before preparing the:','["final documents", "invoices", "staff lists", "lunch menu"]'::jsonb,0,'Preliminary work comes first.','original'),
('127.418.d.9.J',4,'A preliminary drawing may leave out fine details so the team can quickly compare:','["paint chips", "design alternatives", "door handles", "carpet pieces"]'::jsonb,1,'Early sketches are for comparing.','original'),
('127.418.d.9.K',3,'Placing the long side of a house toward the south in the northern hemisphere helps capture winter:','["wind noise", "rain", "sunlight", "snow plows"]'::jsonb,2,'South glazing gains winter sun.','original'),
('127.418.d.9.K',4,'A site plan that orients a building to maximize daylight also considers the effect on its neighbors'' access to:','["parking only", "utilities only", "mailing addresses", "light and views"]'::jsonb,3,'Site planning considers surroundings.','original'),
('127.418.d.9.L',3,'A building plan is drawn as seen from above after a horizontal cut about four feet above the:','["floor", "roof peak", "garage door", "ceiling joist"]'::jsonb,0,'Plans cut through walls.','original'),
('127.418.d.9.M',3,'A wall section shows the thickness and layers of a wall, drawn to scale from the foundation to the:','["parking lot", "roof", "sewer", "sidewalk"]'::jsonb,1,'Sections show layers.','original'),
('127.418.d.9.M',4,'Interior elevations show the walls of a room, including cabinets and:','["clouds", "trees", "fixtures", "tires"]'::jsonb,2,'Interior elevations show finishes.','original'),
('127.418.d.9.N',3,'A detail drawing is drawn at a larger scale than a plan to show how a small portion, such as a window head, is:','["approved", "named", "taxed", "assembled"]'::jsonb,3,'Details show construction.','original'),
('127.418.d.9.N',4,'Ceiling and roof sections show the layers of structure, insulation, and finishes above a:','["room", "pond", "road", "park"]'::jsonb,0,'Sections show vertical layers.','original'),
('127.418.d.9.O',3,'After a code review finds that a stair is too narrow, the drafter updates the drawings to reflect the:','["weather", "reviewer''s comments", "music", "lunch order"]'::jsonb,1,'Reviews drive revisions.','original'),
('127.418.d.9.O',4,'Revising construction documents after a code review helps the project avoid a rejected:','["paint order", "lunch break", "permit application", "trophy"]'::jsonb,2,'Compliance is checked before permit approval.','original'),
('127.418.d.9.P',3,'The structural engineer''s calculations show a beam needs to be deeper, so the drawings are revised to incorporate the engineer''s:','["jokes", "gossip", "hobbies", "results"]'::jsonb,3,'Analysis updates the drawings.','original'),
('127.418.d.9.P',4,'Coordinating revisions between architectural and structural drawings prevents the contractor from building something that:','["does not fit or work", "looks interesting", "has color", "costs nothing"]'::jsonb,0,'Coordination avoids conflicts.','original'),
('127.418.d.10.A',3,'A utility easement, a steep slope, and a flood zone are all examples of site:','["bonuses", "constraints", "colors", "slogans"]'::jsonb,1,'Constraints limit the layout.','original'),
('127.418.d.10.A',4,'Existing overhead power lines that cross a lot limit where a tall building can be placed because they require a:','["tenant vote", "name change", "clearance distance", "new paint color"]'::jsonb,2,'Utilities limit development.','original'),
('127.418.d.10.B',3,'Low impact development uses features such as rain gardens and permeable pavement to manage stormwater:','["only after it floods", "far from the site", "by ignoring it", "close to its source"]'::jsonb,3,'LID mimics natural processes.','original'),
('127.418.d.10.B',4,'A purpose of low impact development is to reduce runoff and the pollutants it carries into:','["streams and rivers", "elevators", "offices", "parking garages"]'::jsonb,0,'LID protects receiving waters.','original'),
('127.418.d.10.C',3,'A preliminary site drawing shows existing trees, slopes, and utilities so the designer can decide where to place the:','["clock", "building", "moon", "weather"]'::jsonb,1,'Early drawings test layouts.','original'),
('127.418.d.10.C',4,'Showing the property lines and setbacks on a preliminary site drawing identifies the area where building is:','["hidden", "dangerous", "permitted", "mandatory"]'::jsonb,2,'The buildable area is within setbacks.','original'),
('127.418.d.10.D',3,'Engineering plans for a building site integrate solutions for grading, drainage, and:','["trophies", "menus", "games", "utilities"]'::jsonb,3,'Site plans combine systems.','original'),
('127.418.d.10.D',4,'A site plan that sends downspouts to a rain garden integrates a stormwater solution with the site''s:','["landscape", "fire alarm", "music system", "elevator"]'::jsonb,0,'Systems are integrated.','original'),
('127.418.d.10.E',3,'Sandy soils drain quickly, while clay soils drain slowly and can hold water, which affects where a designer places a:','["bench", "septic or drainage system", "mailbox", "flagpole"]'::jsonb,1,'Drainage depends on soil.','original'),
('127.418.d.10.E',4,'Expansive clay under a slab can lift and crack it, so a designer may recommend a stiffened slab or soil:','["decoration", "rental", "treatment", "sale"]'::jsonb,2,'Soil properties shape the foundation.','original'),
('127.418.d.10.F',3,'Parking areas, walkways, and retention ponds are examples of site:','["hobbies", "rumors", "books", "features"]'::jsonb,3,'Site features are sized and placed in the plan.','original'),
('127.418.d.10.F',4,'The number of parking spaces required by the city for a restaurant helps determine the size of the site''s:','["parking lot", "roof color", "front sign", "kitchen menu"]'::jsonb,0,'Sizing follows requirements.','original'),
('127.418.d.10.G',3,'Before locating a building on a site, the designer evaluates sun path, wind, views, and:','["phone plans", "access to roads", "menus", "friend lists"]'::jsonb,1,'Site evaluation guides orientation.','original'),
('127.418.d.10.G',4,'Placing a building on higher ground within a lot reduces the risk of:','["phone calls", "visitors", "flooding", "sunshine"]'::jsonb,2,'Site evaluation reduces risk.','original'),
('127.418.d.10.H',3,'Advanced CAD tools for site drawings can show contours, grading, and:','["song titles", "movie times", "recipes", "proposed roads"]'::jsonb,3,'CAD supports site design.','original'),
('127.418.d.10.H',4,'Creating a 3D surface in CAD from survey points helps the designer see how the proposed grading changes the:','["terrain", "weather", "zoning", "budget"]'::jsonb,0,'Surface models show terrain.','original'),
('127.418.d.10.I',3,'After finishing a site design, the team shares it with reviewers and revises it based on their:','["jokes", "feedback", "uniforms", "lunch"]'::jsonb,1,'Presentation leads to improvement.','original'),
('127.418.d.10.I',4,'Presenting a site design clearly to reviewers requires labeling the key features and explaining how the design meets the:','["owner''s hobbies", "building colors only", "project goals", "bus schedule"]'::jsonb,2,'Presentations connect design to goals.','original'),
('127.418.d.11.A',3,'A floor plan shows a room 12 ft by 15 ft. The area of its floor is:','["27 square feet", "54 square feet", "1,800 square feet", "180 square feet"]'::jsonb,3,'12 x 15 = 180.','original'),
('127.418.d.11.A',4,'Flooring comes in boxes covering 20 square feet. A 180 square foot room needs at least how many boxes?','["9", "10", "8", "18"]'::jsonb,0,'180 / 20 = 9.','original'),
('127.418.d.11.B',3,'A material quantity take-off for a wall counts the number of studs, sheets of drywall, and:','["clouds", "linear feet of trim", "songs", "tenants"]'::jsonb,1,'Take-offs list material amounts.','original'),
('127.418.d.11.B',4,'A wall is 40 ft long and 8 ft high, and studs are spaced 16 inches apart. The studs needed for the straight wall, counting one at the start, are about:','["10", "41", "31", "25"]'::jsonb,2,'480 inches / 16 = 30, plus one = 31.','original'),
('127.418.d.11.C',3,'An opinion of probable cost for a building adds the costs of materials, labor, equipment, and:','["tour guides", "paint choices", "lunch", "contractor overhead and profit"]'::jsonb,3,'An OPC includes all costs.','original'),
('127.418.d.11.C',4,'An OPC is prepared early in design to help the owner decide whether the project fits the available:','["budget", "staff", "time", "color"]'::jsonb,0,'Estimates guide go or no-go.','original'),
('127.418.d.11.D',3,'Documenting that a window meets the code requires the designer to cite the product''s tested:','["shipping color", "performance rating", "shelf location", "manufacturer''s slogan"]'::jsonb,1,'Documentation shows compliance.','original'),
('127.418.d.11.D',4,'The designer includes code notes on the drawings so that the inspector can verify that the building complies with the:','["architect''s mood", "crew''s lunch", "adopted code", "owner''s wishes"]'::jsonb,2,'Notes prove compliance.','original'),
('127.418.d.11.E',3,'A bid tabulation lists the contractors'' unit prices and totals side by side so the owner can compare:','["maps", "menus", "songs", "bids"]'::jsonb,3,'Tabs organize prices.','original'),
('127.418.d.11.E',4,'On a bid tabulation, the extended price for 200 square yards at 45 dollars per square yard is:','["9,000 dollars", "900 dollars", "245 dollars", "4,500 dollars"]'::jsonb,0,'200 x 45 = 9,000.','original'),
('127.418.d.11.F',3,'Checking that each pay item in a bid matches an item in the plans helps the engineer find a bidder who forgot to include the:','["address", "work", "phone", "lobby"]'::jsonb,1,'Complete bids cover all work.','original'),
('127.418.d.11.F',4,'If one bid''s total is much lower than the rest, the engineer should check for missing items or unbalanced:','["shipping dates", "window styles", "unit prices", "paint colors"]'::jsonb,2,'Unusual bids need review.','original'),
('127.418.d.11.G',3,'To create a bid tabulation, the engineer lists every pay item in rows and each contractor''s prices in:','["songs", "maps", "poems", "columns"]'::jsonb,3,'Tabs are tables.','original'),
('127.418.d.11.G',4,'The lowest total on a bid tabulation is not automatically the winner if the bidder is not:','["responsible and responsive", "local", "famous", "well dressed"]'::jsonb,0,'Awards require qualified bidders.','original'),
('127.418.d.11.H',3,'A construction project manual includes the bidding documents, the contract, and the written:','["jokes", "specifications", "cartoons", "lyrics"]'::jsonb,1,'The manual holds written requirements.','original'),
('127.418.d.11.H',4,'General conditions in a project manual describe the rights and duties of the owner and the:','["competitor", "reporter", "contractor", "tourist"]'::jsonb,2,'Conditions define roles.','original'),
('127.418.d.11.I',3,'An organizational chart for a construction project shows who reports to whom, such as the superintendent reporting to the:','["delivery driver", "janitor", "visitor", "project manager"]'::jsonb,3,'Org charts show reporting lines.','original'),
('127.418.d.11.I',4,'A Gantt chart for construction lists activities, such as foundation, framing, and roofing, in the order they must be:','["performed", "photographed", "named", "painted"]'::jsonb,0,'Sequences show order.','original'),
('127.419.d.1.A',3,'A county asks a survey firm why its road map keeps showing the wrong boundary. Stating this question precisely is the first step of:','["selling the maps", "defining the problem", "closing the office", "printing the maps"]'::jsonb,1,'Defining the problem starts the design process.','original'),
('127.419.d.1.A',4,'Skipping the problem-definition step often leads a surveying team to collect data that does not help answer the:','["weather report", "budget form", "real question", "data sheet"]'::jsonb,2,'A vague problem wastes field time.','original'),
('127.419.d.1.B',3,'Before staking a subdivision, a survey team studies old plats, deeds, and existing control points. This is the design process stage of:','["demolition", "celebration", "retirement", "research"]'::jsonb,3,'Research gathers background information.','original'),
('127.419.d.1.B',4,'Looking up how earlier surveyors marked corners helps a crew learn which methods are most likely to:','["find the original corners", "move the corners", "lose the corners", "hide the corners"]'::jsonb,0,'Past practice informs fieldwork.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
