select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.419.d.1.C',3,'Listing many possible ways to measure an inaccessible river width is an example of:','["inspection", "ideation", "closeout", "billing"]'::jsonb,1,'Ideation produces options.','original'),
('127.419.d.1.C',4,'Turning the river-width idea into a plan with equipment, steps, and expected accuracy is:','["abandonment", "retirement", "conceptualization", "litigation"]'::jsonb,2,'Concepts add detail to ideas.','original'),
('127.419.d.1.D',3,'A crew compares three ways to measure a long baseline and chooses the one with the best accuracy for the cost. This is:','["renewing a license", "filing a plat", "naming a baseline", "selecting a solution"]'::jsonb,3,'Selection compares options against criteria.','original'),
('127.419.d.1.D',4,'Choosing a method for a boundary survey should depend on the accuracy needed and the:','["site conditions", "map border", "surveyor''s hobbies", "truck color"]'::jsonb,0,'Context drives method choice.','original'),
('127.419.d.1.E',3,'A hand-drawn sketch of a lot, a scaled map, and a 3D terrain model each serve a different purpose, but only the scaled map is a:','["cartoon", "technical drawing", "poem", "greeting"]'::jsonb,1,'Technical drawings follow standards.','original'),
('127.419.d.1.E',4,'A physical model of terrain built from survey data helps a client understand:','["how much the surveyor charges", "what the weather was", "how the land slopes", "where the office is"]'::jsonb,2,'Models communicate form.','original'),
('127.419.d.1.F',3,'A surveyor checks a new total station by measuring a distance already known to be exact. This kind of check is a:','["social visit", "budget talk", "parade", "calibration test"]'::jsonb,3,'Known references reveal error.','original'),
('127.419.d.1.F',4,'Repeating a measurement several times and comparing the results is part of designing a test that can show:','["how reliable the method is", "how loud the crew is", "how far the van drove", "how old the tape is"]'::jsonb,0,'Repetition measures reliability.','original'),
('127.419.d.1.G',3,'If field data show the traverse does not close, the crew goes back, rechecks the measurements, and tries again, which shows the process is:','["guaranteed", "iterative", "finished", "accidental"]'::jsonb,1,'Iteration refines results.','original'),
('127.419.d.1.G',4,'Reviewing a failed closure can reveal which step to improve, so feedback in an iterative process helps the team to:','["skip the field work", "repeat the same error", "improve the next attempt", "hide the data"]'::jsonb,2,'Feedback drives improvement.','original'),
('127.419.d.1.H',3,'After a survey is complete, the surveyor shares results with the client in a clear drawing and report. This is the purpose of:','["skipping the report", "destroying the data", "hiding the map", "communicating the solution"]'::jsonb,3,'Communication delivers the results.','original'),
('127.419.d.1.H',4,'A final survey plat must show enough detail that another surveyor could:','["retrace the boundaries", "redo the tax bills", "repaint the signs", "rename the roads"]'::jsonb,0,'Clear documentation supports repeatability.','original'),
('127.419.d.2.A',3,'A survey crew chief plans each day''s field tasks around sunrise and traffic, practicing:','["time zoning", "time management", "time travel", "time painting"]'::jsonb,1,'Planning manages limited time.','original'),
('127.419.d.2.A',4,'Setting an internal deadline earlier than the client''s helps a team handle surprises, such as a:','["new logo", "phone upgrade", "missing monument", "holiday party"]'::jsonb,2,'Buffers absorb delays.','original'),
('127.419.d.2.B',3,'A property that can only be surveyed after the owner gives permission to enter faces a constraint called:','["weather", "drawing scale", "map color", "legal access"]'::jsonb,3,'Access can limit work.','original'),
('127.419.d.2.B',4,'If heavy rain makes a river impassable, a crew plans the stream cross-section survey for another day, showing the value of:','["planning around constraints", "ignoring weather", "wasting time", "avoiding work"]'::jsonb,0,'Plans adapt to constraints.','original'),
('127.419.d.2.C',3,'Completing the control survey by Friday and the boundary drawing by next Wednesday are examples of:','["errors", "milestones and deliverables", "jokes", "hobbies"]'::jsonb,1,'Milestones mark progress.','original'),
('127.419.d.2.C',4,'Dividing a large survey into stages with deliverables lets the client review the work before it is:','["taxed", "lost", "finished", "named"]'::jsonb,2,'Stages support checkpoints.','original'),
('127.419.d.2.D',3,'A quick radio call between crew members is informal, while a certified plat delivered to a county is:','["a rumor", "a joke", "small talk", "formal communication"]'::jsonb,3,'Formal documents carry weight.','original'),
('127.419.d.2.D',4,'A surveyor emails a landowner a short question about a fence line. An email is a good choice because it creates a written:','["record", "guess", "noise", "rumor"]'::jsonb,0,'Written messages document facts.','original'),
('127.419.d.2.E',3,'When a measured angle does not agree with the plat, a crew rechecks each step one at a time, using a method of:','["giving up", "systematic troubleshooting", "wishful thinking", "random guessing"]'::jsonb,1,'Careful checking finds errors.','original'),
('127.419.d.2.E',4,'Working with other crew members to compare notes can solve a field problem faster because each person may notice a different:','["holiday", "hobby", "detail", "rumor"]'::jsonb,2,'Collaboration finds answers.','original'),
('127.419.d.3.A',3,'Employers must provide a worksite free of recognized serious hazards. Employees must also follow safety rules and use the:','["newest phone", "loudest radio", "fastest route", "required protective equipment"]'::jsonb,3,'Safety is a shared duty.','original'),
('127.419.d.3.A',4,'A surveyor who sees a hole hidden by tall grass near a traverse point should mark it and tell the crew, which shows the worker duty to:','["report hazards", "remove the notes", "ignore the area", "avoid mapping"]'::jsonb,0,'Workers share hazard information.','original'),
('127.419.d.3.B',3,'Standards from the Occupational Safety and Health Administration help protect workers by setting minimum rules for:','["map colors", "workplace safety", "tool prices", "lunch breaks only"]'::jsonb,1,'OSHA sets safety rules.','original'),
('127.419.d.3.B',4,'Road survey crews who work near traffic must follow OSHA rules, which are important because they reduce the chance of:','["losing a pencil", "getting a sunburn", "being struck by a vehicle", "running out of paint"]'::jsonb,2,'Work-zone safety saves lives.','original'),
('127.419.d.3.C',3,'Measuring noise or dust that crew members are exposed to on a job is part of industrial hygiene, which protects worker:','["fashion", "pay", "schedules", "health"]'::jsonb,3,'Hygiene prevents exposure illnesses.','original'),
('127.419.d.3.C',4,'Long-term sun exposure is a health hazard for field crews, and a control that helps is to use:','["sunscreen, hats, and shade", "longer tapes", "darker maps", "bigger stakes"]'::jsonb,0,'Controls reduce exposure.','original'),
('127.419.d.3.D',3,'A surveyor working along a highway wears a bright vest so drivers can see her, which is a type of:','["drawing tool", "personal protective equipment", "tracking device", "calendar"]'::jsonb,1,'High-visibility gear is PPE.','original'),
('127.419.d.3.D',4,'Steel-toe boots, gloves, and eye protection are chosen based on the hazards of the job, such as sharp tools and flying:','["maps", "emails", "debris", "songs"]'::jsonb,2,'PPE depends on the hazard.','original'),
('127.419.d.3.E',3,'Steep slopes, loose rocks, and uneven ground are examples of unsafe walking surfaces that can cause a:','["sale", "sunburn", "power outage", "slip or fall"]'::jsonb,3,'Footing matters outdoors.','original'),
('127.419.d.3.E',4,'When working on a slippery stream bank, a safe practice is to keep three points of contact and wear boots with good:','["traction", "color", "sound", "paint"]'::jsonb,0,'Traction prevents slips.','original'),
('127.419.d.3.F',3,'A survey rod made of metal can conduct electricity, so holding it near an overhead power line risks:','["paperwork", "electrocution", "sunburn", "boredom"]'::jsonb,1,'Metal rods near lines are deadly.','original'),
('127.419.d.3.F',4,'Before extending a long rod on a site, a crew member should look up to check for:','["clouds", "birds", "power lines", "signs"]'::jsonb,2,'Look for overhead hazards.','original'),
('127.419.d.3.G',3,'Fuel for a generator or paint cans for marking should be stored in approved containers because they can be:','["edible", "musical", "colorful", "flammable"]'::jsonb,3,'Fuels burn.','original'),
('127.419.d.3.G',4,'A crew that transports aerosol marking paint in a hot truck cab risks a can:','["bursting from pressure", "freezing", "gaining weight", "changing color"]'::jsonb,0,'Heat raises can pressure.','original'),
('127.419.d.3.H',3,'A first aid kit, a fire extinguisher, and a posted list of emergency phone numbers are workplace health and safety:','["puzzles", "resources", "games", "rumors"]'::jsonb,1,'Resources support response.','original'),
('127.419.d.3.H',4,'A crew working far from town should know the nearest hospital and carry a charged phone or radio so they can:','["check scores", "post photos", "call for help", "order food"]'::jsonb,2,'Emergency planning saves time.','original'),
('127.419.d.3.I',3,'A company safety and health program has management leadership, worker participation, and a process for finding and fixing:','["trophies", "logos", "slogans", "hazards"]'::jsonb,3,'Programs control hazards.','original'),
('127.419.d.3.I',4,'Asking field workers for input on a safety program improves it because they are closest to the real:','["risks", "maps", "emails", "bills"]'::jsonb,0,'Worker insight improves programs.','original'),
('127.419.d.3.J',3,'A written emergency action plan tells workers how to report a fire and how to:','["change shifts", "evacuate", "buy tools", "order lunch"]'::jsonb,1,'Plans give clear steps.','original'),
('127.419.d.3.J',4,'Doing a drill of the plan helps workers find weak spots in the procedure before a real:','["delivery", "vacation", "emergency", "holiday"]'::jsonb,2,'Drills reveal gaps.','original'),
('127.419.d.3.K',3,'The hazard communication standard requires employers to train workers about the chemicals they use and to keep:','["lunch menus", "sale flyers", "vacation lists", "safety data sheets"]'::jsonb,3,'HazCom requires SDSs.','original'),
('127.419.d.3.K',4,'A label with an exclamation mark pictogram warns of a less serious hazard, such as skin:','["irritation", "music", "decoration", "height"]'::jsonb,0,'Pictograms show hazard types.','original'),
('127.419.d.3.L',3,'New employees must be trained on the hazards of their tasks before they:','["get a raise", "begin the work", "sign a lease", "go home"]'::jsonb,1,'Training comes first.','original'),
('127.419.d.3.L',4,'Annual refresher training helps workers stay current on safety rules, which are updated as:','["holidays pass", "menus rotate", "hazards and regulations change", "seasons start"]'::jsonb,2,'Retraining keeps skills current.','original'),
('127.419.d.4.A',3,'Distances measured as 100.2, 100.4, and 100.0 meters have a mean of:','["100.0 m", "100.4 m", "300.6 m", "100.2 m"]'::jsonb,3,'(100.2 + 100.4 + 100.0)/3 = 100.2.','original'),
('127.419.d.4.A',4,'Elevations of 10.1, 10.3, 10.2, 10.2, and 11.0 feet have a median of:','["10.2 ft", "10.3 ft", "11.0 ft", "10.56 ft"]'::jsonb,0,'The middle value of the ordered data is 10.2.','original'),
('127.419.d.4.B',3,'A set of angle readings that are all very close together has a small:','["sum of angles", "standard deviation", "mean angle", "maximum angle"]'::jsonb,1,'Tight data have low spread.','original'),
('127.419.d.4.B',4,'If two crews measure the same line and Crew A''s readings spread more widely than Crew B''s, Crew A''s standard deviation is:','["negative", "smaller", "larger", "zero"]'::jsonb,2,'More spread, larger SD.','original'),
('127.419.d.4.C',3,'The bell-shaped curve that describes many random measurement errors is called a:','["square wave", "spiral", "straight line", "normal distribution"]'::jsonb,3,'Random errors are often normally distributed.','original'),
('127.419.d.4.C',4,'The peak of the normal curve of a set of repeated distance measurements is centered at the:','["mean", "range", "maximum reading", "minimum reading"]'::jsonb,0,'The center is the average.','original'),
('127.419.d.4.D',3,'The Empirical Rule predicts that about 95 percent of data lie within two standard deviations of the:','["median only", "mean", "maximum", "range"]'::jsonb,1,'68-95-99.7.','original'),
('127.419.d.4.D',4,'A measurement set has mean 50.00 m and standard deviation 0.02 m. About 68 percent of values will lie between:','["49.00 m and 51.00 m", "49.90 m and 50.10 m", "49.98 m and 50.02 m", "49.96 m and 50.04 m"]'::jsonb,2,'Mean plus or minus 1 SD.','original'),
('127.419.d.4.E',3,'A tape that is stretched slightly wrong causes every measurement to be long by the same amount. This is a:','["blunder", "random error", "tolerance", "systematic error"]'::jsonb,3,'Constant bias is systematic.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.419.d.4.E',4,'Small, unpredictable variations from reading to reading, caused by things like wind or hand tremor, are called:','["random errors", "systematic errors", "blunders", "corrections"]'::jsonb,0,'Random errors vary unpredictably.','original'),
('127.419.d.4.F',3,'Shots that are tightly clustered but far from the bullseye describe measurements that are:','["accurate but not precise", "precise but not accurate", "neither precise nor accurate", "both accurate and precise"]'::jsonb,1,'Tight cluster off target.','original'),
('127.419.d.4.F',4,'Shots scattered around the bullseye with the average at the center describe measurements that are:','["exactly perfect", "useless always", "accurate on average but not precise", "precise and inaccurate"]'::jsonb,2,'Spread but centered.','original'),
('127.419.d.4.G',3,'A polygon with five sides is a:','["octagon", "hexagon", "triangle", "pentagon"]'::jsonb,3,'Pentagon means five sides.','original'),
('127.419.d.4.G',4,'The sum of the interior angles of any four-sided polygon is:','["360 degrees", "720 degrees", "180 degrees", "540 degrees"]'::jsonb,0,'A quadrilateral sums to 360.','original'),
('127.419.d.4.H',3,'A right triangle has legs 6 ft and 8 ft. By the Pythagorean theorem the hypotenuse is:','["48 ft", "10 ft", "100 ft", "14 ft"]'::jsonb,1,'36 + 64 = 100, square root = 10.','original'),
('127.419.d.4.H',4,'From a point 60 ft from the base of a 60 ft tower on level ground, the angle of elevation to the top is:','["30 degrees", "60 degrees", "45 degrees", "90 degrees"]'::jsonb,2,'tan 45 = 1, so distance equals height.','original'),
('127.419.d.4.I',3,'A line segment connecting two points on a circle and passing through its center is a:','["arc", "tangent", "sector", "diameter"]'::jsonb,3,'A diameter passes through the center.','original'),
('127.419.d.4.I',4,'A segment that touches a circle at one point and does not cross inside is a:','["tangent", "radius", "secant", "chord"]'::jsonb,0,'Tangents touch once.','original'),
('127.419.d.4.J',3,'A circular tank has a diameter of 10 m. Its radius is:','["20 m", "5 m", "10 m", "2.5 m"]'::jsonb,1,'Radius is half the diameter.','original'),
('127.419.d.4.J',4,'A circle has a radius of 3 m. Using pi = 3.14, its area is about:','["56.5 square meters", "9.4 square meters", "28.3 square meters", "18.8 square meters"]'::jsonb,2,'3.14 x 9 = 28.26.','original'),
('127.419.d.4.K',3,'A road rises 2 feet for every 50 feet of horizontal distance. Its slope as a fraction is:','["25", "50", "1/2", "1/25"]'::jsonb,3,'2/50 = 1/25.','original'),
('127.419.d.4.K',4,'A line has the equation y = 3x - 2. Its y-intercept is:','["-2", "2", "3", "-3"]'::jsonb,0,'In y = mx + b, b is the y-intercept.','original'),
('127.419.d.4.L',3,'The volume of a rectangular box 4 m by 3 m by 2 m is:','["48 cubic meters", "24 cubic meters", "12 cubic meters", "9 cubic meters"]'::jsonb,1,'4 x 3 x 2 = 24.','original'),
('127.419.d.4.L',4,'A cylinder-shaped well casing has a radius of 0.5 ft and a height of 20 ft. Using pi = 3.14, the volume is about:','["3.14 cubic feet", "31.4 cubic feet", "15.7 cubic feet", "62.8 cubic feet"]'::jsonb,2,'3.14 x 0.25 x 20 = 15.7.','original'),
('127.419.d.5.A',3,'Imaginary lines that run east-west and measure position north or south of the equator are lines of:','["magnitude", "altitude", "longitude", "latitude"]'::jsonb,3,'Latitude measures north-south position.','original'),
('127.419.d.5.A',4,'Longitude measures position east or west of the:','["prime meridian", "equator", "pole", "tropic"]'::jsonb,0,'Prime meridian is 0 degrees longitude.','original'),
('127.419.d.5.B',3,'A GPS survey method that uses a base station and a rover, and gets centimeter accuracy, is called:','["radio guess", "real-time kinematic", "dead reckoning", "static camera"]'::jsonb,1,'RTK uses corrections.','original'),
('127.419.d.5.B',4,'Static GPS surveying collects data over a longer time than RTK and is used when the highest possible:','["price is low", "cost is irrelevant", "accuracy is required", "speed is needed"]'::jsonb,2,'Long sessions improve accuracy.','original'),
('127.419.d.5.C',3,'Occupying a mark with a GPS receiver for several hours and processing the data to get its latitude and longitude is called tying down a:','["road", "bill", "contract", "point"]'::jsonb,3,'Tie-downs establish coordinates.','original'),
('127.419.d.5.C',4,'A tie-down to the National Spatial Reference System gives the point coordinates that match the national:','["datum", "clock", "tax roll", "calendar"]'::jsonb,0,'Coordinates reference a datum.','original'),
('127.419.d.5.D',3,'GPS has three segments: the space segment of satellites, the control segment of ground stations, and the user segment of:','["tapes", "receivers", "pencils", "maps"]'::jsonb,1,'Receivers are the user segment.','original'),
('127.419.d.5.D',4,'The control segment of GPS monitors the satellites and updates their:','["color", "paint", "orbit and clock data", "weight"]'::jsonb,2,'Ground stations maintain satellite data.','original'),
('127.419.d.5.E',3,'A GPS satellite continuously broadcasts its position and the exact:','["weather", "color", "price", "time"]'::jsonb,3,'Timing signals enable ranging.','original'),
('127.419.d.5.E',4,'GPS satellites carry atomic clocks because positioning depends on measuring tiny differences in signal:','["travel time", "volume", "sound", "color"]'::jsonb,0,'Timing errors become range errors.','original'),
('127.419.d.5.F',3,'GPS ground stations track the satellites and send them corrections so that their signals remain:','["colorful", "accurate", "slow", "loud"]'::jsonb,1,'Control stations correct orbits.','original'),
('127.419.d.5.F',4,'The master control station for GPS collects data from monitor stations around the world to calculate precise:','["tax rates", "time zones", "satellite orbits", "road maps"]'::jsonb,2,'Orbits are computed from monitor data.','original'),
('127.419.d.5.G',3,'A GPS receiver measures its distance from several satellites to determine its:','["weight", "color", "age", "position"]'::jsonb,3,'Receivers compute location.','original'),
('127.419.d.5.G',4,'A receiver needs signals from at least four satellites to solve for its three position coordinates and its:','["clock error", "tire pressure", "battery size", "paint color"]'::jsonb,0,'Four unknowns need four signals.','original'),
('127.419.d.5.H',3,'A map made using geodetic coordinates plots points by their latitude and longitude on a model of the:','["moon", "Earth", "sun", "office"]'::jsonb,1,'Geodetic coordinates reference the Earth.','original'),
('127.419.d.5.H',4,'When plotting survey points on a flat map from geodetic coordinates, the surveyor first converts them with a map:','["cartoon", "legend", "projection", "border"]'::jsonb,2,'Projections flatten the globe.','original'),
('127.419.d.6.A',3,'A theodolite combines a telescope with graduated circles that measure horizontal and vertical:','["colors", "weights", "prices", "angles"]'::jsonb,3,'Optomechanical instruments measure angles.','original'),
('127.419.d.6.A',4,'The leveling screws and bubble on a survey instrument are used to make its vertical axis truly:','["plumb", "portable", "colorful", "hot"]'::jsonb,0,'Leveling aligns the instrument.','original'),
('127.419.d.6.B',3,'An instrument that sets a horizontal line of sight so that rod readings can find differences in height is the:','["drafting pencil", "level", "compass rose", "plumb bob only"]'::jsonb,1,'Levels measure elevation differences.','original'),
('127.419.d.6.B',4,'A total station combines an angle-measuring theodolite with an electronic way to measure:','["weather", "sound", "distance", "color"]'::jsonb,2,'Total stations measure angles and distances.','original'),
('127.419.d.6.C',3,'A small aircraft flown without an onboard pilot and used to photograph a site for mapping is a:','["stake", "tape", "bulldozer", "UAV or drone"]'::jsonb,3,'UAVs collect aerial data.','original'),
('127.419.d.6.C',4,'A remote sensing method that sends laser pulses to the ground to measure many elevation points rapidly is:','["LiDAR", "hand sketch", "paper tracing", "radio guess"]'::jsonb,0,'LiDAR creates dense point clouds.','original'),
('127.419.d.6.D',3,'A steel tape, an odometer wheel, and an electronic range finder are all tools for measuring:','["angles", "distance", "temperature", "time"]'::jsonb,1,'These tools measure length.','original'),
('127.419.d.6.D',4,'Over a long line, the most accurate of a steel tape, a measuring wheel, and an instrument that times a reflected signal is typically the:','["paced steps", "measuring wheel", "electronic distance meter", "guess"]'::jsonb,2,'EDMs are precise over long ranges.','original'),
('127.419.d.6.E',3,'Measuring a line by laying a tape end to end along the ground is called:','["pacing", "plotting", "sighting", "taping"]'::jsonb,3,'Taping is direct measurement.','original'),
('127.419.d.6.E',4,'Methods that determine distance by measuring the time a signal takes to travel to a target and back are called:','["electronic distance measurement", "chaining by eye", "pacing", "estimating"]'::jsonb,0,'EDM measures travel time.','original'),
('127.419.d.6.F',3,'A crew measures the distance between two points on the ground twice, once with a tape and once with an EDM. The first step in doing this is to:','["guess", "set up and record each reading", "destroy the stakes", "ignore the readings"]'::jsonb,1,'Careful recording supports comparison.','original'),
('127.419.d.6.F',4,'When measuring a slope distance with a tape, the surveyor must correct the reading to a:','["lower number", "vertical angle only", "horizontal distance", "color"]'::jsonb,2,'Surveys use horizontal distances.','original'),
('127.419.d.6.G',3,'A tape reading of 100.03 m and an EDM reading of 100.01 m differ by:','["200 m", "2 m", "0.2 m", "0.02 m"]'::jsonb,3,'100.03 - 100.01 = 0.02.','original'),
('127.419.d.6.G',4,'After comparing the data from two measuring tools, the crew should trust the result from the tool that has the smaller:','["uncertainty", "handle", "price", "weight"]'::jsonb,0,'Smaller uncertainty is better.','original'),
('127.419.d.6.H',3,'A protractor, a compass, and a theodolite are tools for measuring:','["times", "angles", "weights", "distances"]'::jsonb,1,'These measure angular data.','original'),
('127.419.d.6.H',4,'Of a protractor, a compass, and an instrument with a telescope and graduated circles, the one with the finest angular readout is the:','["protractor", "ruler", "theodolite", "compass"]'::jsonb,2,'Theodolites read to seconds.','original'),
('127.419.d.6.I',3,'Measuring the angle between two lines of sight by turning a telescope from one target to the other uses the method of:','["pacing", "tracing", "estimating", "direct angle measurement"]'::jsonb,3,'Angles are read between sightings.','original'),
('127.419.d.6.I',4,'Repeating an angle several times and averaging the results is a way to reduce the effect of:','["random reading errors", "weather forecasts", "sunlight", "gravity"]'::jsonb,0,'Repetition reduces random error.','original'),
('127.419.d.6.J',3,'A magnetic compass shows an angle called a bearing, which is measured from:','["the equator", "north", "the sun at noon", "the nearest road"]'::jsonb,1,'Bearings reference north.','original'),
('127.419.d.6.J',4,'The difference between true north and magnetic north at a location is called:','["scale factor", "traverse error", "magnetic declination", "contour interval"]'::jsonb,2,'Compasses need correction for declination.','original'),
('127.419.d.6.K',3,'A theodolite reads an angle as 45 degrees 10 minutes, and a compass gives 46 degrees. The two differ by:','["about 5 minutes", "about 5 degrees", "about 90 degrees", "about 50 minutes"]'::jsonb,3,'46° = 46°00′; difference = 50′.','original'),
('127.419.d.6.K',4,'When different angle-measuring tools disagree, the surveyor should consider the precision of each tool and check for:','["blunders or setup errors", "tool color", "extra data", "weather names"]'::jsonb,0,'Disagreement signals errors.','original'),
('127.419.d.6.L',3,'The National Geodetic Survey maintains a network of points with known positions called:','["street signs", "control points", "markers of luck", "price points"]'::jsonb,1,'Control points anchor surveys.','original'),
('127.419.d.6.L',4,'A surveyor ties a new survey to NGS monuments so that the survey''s coordinates agree with the:','["tax roll", "owner''s guess", "national reference system", "local newspaper"]'::jsonb,2,'Ties unify surveys.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
