select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.419.d.6.M',3,'A level, a theodolite, and a GPS receiver can each be used to determine a point''s:','["taste", "weight", "price", "elevation"]'::jsonb,3,'These tools can measure height.','original'),
('127.419.d.6.M',4,'Of those tools, the level is generally most precise for finding the:','["difference in height between nearby points", "size of a lot", "angle to the sun", "position on the globe"]'::jsonb,0,'Differential leveling is precise.','original'),
('127.419.d.6.N',3,'A theodolite reads a vertical angle of 45 degrees to the top of a tower. The tower''s height above the instrument divided by the horizontal distance to it equals the tangent of 45 degrees, which is:','["0.5", "1", "2", "0"]'::jsonb,1,'tan 45 = 1.','original'),
('127.419.d.6.N',4,'To find the full height of an object using a theodolite, the surveyor adds the calculated rise to the:','["map scale", "zip code", "height of the instrument", "owner''s name"]'::jsonb,2,'The telescope is above the ground.','original'),
('127.419.d.6.O',3,'A benchmark has an elevation of 100.00 ft. A rod reading on the benchmark is 4.00 ft, and a rod reading on a new point is 6.50 ft. The new point is:','["10.50 ft higher", "4.00 ft higher", "2.50 ft higher", "2.50 ft lower"]'::jsonb,3,'100.00 + 4.00 - 6.50 = 97.50.','original'),
('127.419.d.6.O',4,'Starting from a benchmark of known elevation, a leveling run determines the elevations of other points using the principle of:','["height of instrument", "latitude", "magnetic bearing", "time of flight"]'::jsonb,0,'HI = elevation + backsight.','original'),
('127.419.d.6.P',3,'Two ways of finding the same elevation give 612.31 ft and 612.28 ft. The difference between them is:','["3.0 ft", "0.03 ft", "0.3 ft", "0.003 ft"]'::jsonb,1,'612.31 - 612.28 = 0.03.','original'),
('127.419.d.6.P',4,'When elevation values from two methods differ by more than the tolerance, the crew should:','["erase the notes", "average them blindly", "recheck the work", "ignore both"]'::jsonb,2,'Large differences signal a problem.','original'),
('127.419.d.6.Q',3,'Federal Aviation Administration rules require a person who flies a drone for commercial survey work to hold a:','["fishing license", "boat permit", "parking pass", "remote pilot certificate"]'::jsonb,3,'Part 107 requires certification.','original'),
('127.419.d.6.Q',4,'A UAV operator must keep the aircraft within visual line of sight and below a maximum altitude of:','["400 feet above ground level", "40 feet", "4,000 feet", "40,000 feet"]'::jsonb,0,'Part 107 sets limits.','original'),
('127.419.d.6.R',3,'A survey that shows the location of existing features and ground heights, used to design a project, is a:','["census survey", "topographic survey", "tax survey", "hydrographic survey only"]'::jsonb,1,'Topographic surveys map terrain.','original'),
('127.419.d.6.R',4,'A survey that maps the depth of the bottom of a lake or river is called a:','["boundary survey", "topographic survey", "hydrographic survey", "construction survey"]'::jsonb,2,'Hydrographic surveys map underwater.','original'),
('127.419.d.7.A',3,'A surveyor records measurements as they are taken in a bound field book so there is a permanent record of the:','["music", "weather alone", "lunch", "fieldwork"]'::jsonb,3,'Field notes document the work.','original'),
('127.419.d.7.A',4,'An error in a field book should be crossed out with a single line, not erased, so the original remains:','["legible", "hidden", "destroyed", "missing"]'::jsonb,0,'Never erase field notes.','original'),
('127.419.d.7.B',3,'The cover page of a field book includes the owner''s name, the book number, and the dates:','["spoken", "covered", "hidden", "lost"]'::jsonb,1,'Cover pages identify the book.','original'),
('127.419.d.7.B',4,'A table of contents in a field book lets a later reader find a particular survey by its page and:','["color", "price", "date", "weight"]'::jsonb,2,'Contents aid retrieval.','original'),
('127.419.d.7.C',3,'A level run recorded in a field book lists the station, backsight, height of instrument, foresight, and:','["name", "lunch", "color", "elevation"]'::jsonb,3,'Level notes record each step.','original'),
('127.419.d.7.C',4,'Recording the weather, instrument serial number, and crew members in a field book helps a later reviewer judge the:','["conditions and reliability of the data", "price of the survey", "name of the road", "color of the tape"]'::jsonb,0,'Metadata supports review.','original'),
('127.419.d.8.A',3,'A control survey establishes a framework of precisely located points to which later surveys can be:','["erased", "tied", "sold", "painted"]'::jsonb,1,'Control provides a reference.','original'),
('127.419.d.8.A',4,'A control survey begins with a reconnaissance of the site and then the setting of monuments, followed by measurements and the:','["sale of the land", "printing of the tax bill", "adjustment of the data", "closing of the office"]'::jsonb,2,'Adjustment distributes errors.','original'),
('127.419.d.8.B',3,'A map legend explains the meaning of the symbols on a survey drawing, such as one for a fire hydrant or a:','["cartoon", "song", "tax form", "utility pole"]'::jsonb,3,'Symbols represent features.','original'),
('127.419.d.8.B',4,'A north arrow on a survey drawing is needed so the reader can tell the drawing''s:','["orientation", "price", "weather", "owner"]'::jsonb,0,'A north arrow gives direction.','original'),
('127.419.d.8.C',3,'Software that lets a surveyor draw maps and compute coordinates from field data is called:','["a game", "CAD or survey software", "a calculator app only", "a browser only"]'::jsonb,1,'Survey software supports mapping.','original'),
('127.419.d.8.C',4,'Survey software can check whether a traverse closes by computing the closure:','["paint", "song", "error", "tax"]'::jsonb,2,'Traverse closure shows quality.','original'),
('127.419.d.9.A',3,'Drafting a construction document to scale means each dimension on the sheet is a fixed fraction of the real:','["color", "time", "weight", "length"]'::jsonb,3,'Scale preserves proportion.','original'),
('127.419.d.9.A',4,'At a scale of 1 inch = 50 feet, a feature 200 feet long measures how many inches on the sheet?','["4", "10", "8", "2"]'::jsonb,0,'200 / 50 = 4.','original'),
('127.419.d.9.B',3,'To fit a long site onto a small sheet, the drafter chooses a smaller scale, such as:','["1 inch = 5 feet", "1 inch = 100 feet", "1 inch = 1 foot", "1 inch = 10 feet"]'::jsonb,1,'Larger ratio means smaller drawing.','original'),
('127.419.d.9.B',4,'A site is 600 feet wide and the sheet has room for 12 inches. The largest convenient scale that fits is:','["1 inch = 5 feet", "1 inch = 10 feet", "1 inch = 50 feet", "1 inch = 20 feet"]'::jsonb,2,'600 / 12 = 50.','original'),
('127.419.d.9.C',3,'If the written specifications and the drawing disagree on a pipe size, the drafter and engineer must resolve the:','["date", "color", "title", "conflict"]'::jsonb,3,'Specs and drawings must agree.','original'),
('127.419.d.9.C',4,'A drawing shows what is to be built and where, while the specification states the:','["quality and method of work", "colors of the roads", "costs of lunch", "names of the crew"]'::jsonb,0,'Specs describe materials and workmanship.','original'),
('127.419.d.9.D',3,'The distance between two points on a map projection plane is called the grid distance, while the distance on the ground at the surface is the:','["bearing distance", "ground distance", "angle distance", "paper distance"]'::jsonb,1,'Grid and ground distances differ.','original'),
('127.419.d.9.D',4,'Grid and surface distances differ because the Earth''s surface is curved and the projection flattens it, causing a small:','["bonus", "rainstorm", "distortion", "delay"]'::jsonb,2,'Projections introduce distortion.','original'),
('127.419.d.9.E',3,'A combined scale factor is multiplied by a ground distance to convert it to a:','["weight", "time", "bearing", "grid distance"]'::jsonb,3,'Scale factors transform distances.','original'),
('127.419.d.9.E',4,'A ground distance of 1,000.00 ft with a combined scale factor of 0.9999 gives a grid distance of:','["999.90 ft", "1,000.10 ft", "1,001.00 ft", "990.00 ft"]'::jsonb,0,'1000 x 0.9999 = 999.9.','original'),
('127.419.d.9.F',3,'A topographic map made from field data shows the shape of the land using lines of equal elevation called:','["hedges", "contours", "roads", "borders"]'::jsonb,1,'Contours show relief.','original'),
('127.419.d.9.F',4,'Closely spaced contour lines on a topographic map indicate that the land is:','["flat", "level", "steep", "underwater"]'::jsonb,2,'Close lines mean steep ground.','original'),
('127.419.d.9.G',3,'A surface profile drawn along a baseline on a topographic map shows ground elevation versus:','["time of day", "owner name", "color of soil", "distance along the line"]'::jsonb,3,'Profiles plot elevation against distance.','original'),
('127.419.d.9.G',4,'A profile of a proposed road is drawn with the vertical scale exaggerated compared with the horizontal scale to make changes in:','["elevation easier to see", "labels easier to read", "color easier to match", "distance easier to hide"]'::jsonb,0,'Vertical exaggeration clarifies relief.','original'),
('127.419.d.9.H',3,'Placing stakes in the field at the locations shown on a design plan is called:','["sketching out", "staking out", "clearing in", "staking in"]'::jsonb,1,'Stakeout transfers a design to the ground.','original'),
('127.419.d.9.H',4,'To stake a point from design coordinates, a surveyor uses a total station to turn the proper angle and measure the proper:','["color", "song", "distance", "weight"]'::jsonb,2,'Stakeout needs angle and distance.','original'),
('127.419.d.10.A',3,'When a surveyor finds that a previous surveyor set a monument and the neighbors have relied on it for years, she usually must defer to the work of the:','["newest guess", "neighbor''s opinion", "tax assessor", "original survey"]'::jsonb,3,'Surveyors follow original evidence.','original'),
('127.419.d.10.A',4,'Surveyors retrace original surveys rather than redefine property lines because landowners rely on the boundaries that were:','["originally established", "randomly chosen", "privately changed", "newly invented"]'::jsonb,0,'Retracement protects stability.','original'),
('127.419.d.10.B',3,'Placing permanent markers at the corners of a parcel is called boundary:','["demolition", "monumentation", "advertising", "relocation"]'::jsonb,1,'Monuments mark corners.','original'),
('127.419.d.10.B',4,'A monument is useful as evidence of a boundary only if it is permanent, identifiable, and can be:','["moved easily", "painted over", "found later", "hidden"]'::jsonb,2,'Evidence must be recoverable.','original'),
('127.419.d.10.C',3,'A large oak tree or a river bank used to mark a property corner is a natural:','["tax stamp", "distance", "map symbol", "monument"]'::jsonb,3,'Natural features mark corners.','original'),
('127.419.d.10.C',4,'An iron rod driven in the ground or a concrete marker is an example of an:','["artificial monument", "error", "plat", "natural monument"]'::jsonb,0,'Human-made markers are artificial monuments.','original'),
('127.419.d.10.D',3,'When a river slowly deposits soil on one bank, the boundary of the land may shift according to the rule of:','["partition", "accretion", "reliction", "avulsion"]'::jsonb,1,'Gradual change adjusts the boundary.','original'),
('127.419.d.10.D',4,'A sudden change in a river''s course during a flood is called avulsion, and it usually leaves the boundary:','["given away", "erased", "unchanged at the old location", "moved to the new channel"]'::jsonb,2,'Sudden changes do not shift boundaries.','original'),
('127.419.d.10.E',3,'A legal description of a property uses words, bearings, and distances, or a lot and block reference, to identify the parcel''s:','["paint color", "history of owners", "assessed taxes", "exact location"]'::jsonb,3,'Legal descriptions locate land.','original'),
('127.419.d.10.E',4,'The phrase "Lot 5, Block 3 of the Oak Hills Addition" is a legal description based on a recorded:','["plat", "poem", "photo", "recipe"]'::jsonb,0,'Lot and block refer to a plat.','original'),
('127.419.d.10.F',3,'To find where an original survey placed a boundary, a surveyor researches deeds, plats, and other land:','["trophies", "records", "menus", "tickets"]'::jsonb,1,'Records show the original survey.','original'),
('127.419.d.10.F',4,'Reading the field notes of the first surveyor can help locate a missing corner by describing nearby natural and artificial:','["quotes", "prices", "objects", "grades"]'::jsonb,2,'Original notes include bearing trees and objects.','original'),
('127.419.d.10.G',3,'Much of the land in Texas was first granted to settlers by Spain, Mexico, and later the:','["British Crown", "Roman Empire", "Ottoman Empire", "Republic of Texas"]'::jsonb,3,'Historic land grants shape titles.','original'),
('127.419.d.10.G',4,'Understanding Texas land grants is important to surveyors because many current property boundaries trace back to the:','["original grant surveys", "mapping apps", "modern roads", "recent fads"]'::jsonb,0,'Titles descend from grants.','original'),
('127.419.d.10.H',3,'A boundary survey protects the public by helping to prevent disputes and by showing the extent of a landowner''s:','["television rights", "property rights", "taxes owed to a friend", "favorite colors"]'::jsonb,1,'Surveys clarify ownership.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_68_v1'
from (values
('127.419.d.10.H',4,'A boundary survey can also protect a buyer from discovering after closing that a neighbor''s building:','["has a name", "is visible", "encroaches on the lot", "is painted blue"]'::jsonb,2,'Surveys reveal encroachments.','original'),
('127.419.d.10.I',3,'Using collected field data, a surveyor draws a boundary map that shows the property''s corners, bearings, and:','["colors", "songs", "slogans", "distances"]'::jsonb,3,'Boundary drawings show lengths and directions.','original'),
('127.419.d.10.I',4,'A boundary drawing includes a title block, a north arrow, a scale, and the surveyor''s seal and:','["signature", "lunch menu", "bank number", "pet''s name"]'::jsonb,0,'Seals and signatures certify the plat.','original'),
('127.419.d.10.J',3,'In the order of dignity of calls, natural objects like a creek rank above:','["every other call", "artificial monuments", "no other call", "nothing"]'::jsonb,1,'Natural objects are highest.','original'),
('127.419.d.10.J',4,'If a deed gives a distance of 200 feet but an iron rod is found 203 feet away at the described corner, the dignity of calls says to trust the:','["area", "number", "monument", "distance"]'::jsonb,2,'Monuments outrank distances.','original'),
('127.419.d.11.A',3,'One international foot equals exactly:','["3.2808 meters", "1.0000 meter", "0.3937 meter", "0.3048 meter"]'::jsonb,3,'Defined as 0.3048 m.','original'),
('127.419.d.11.A',4,'A rod 3.048 meters long equals how many international feet?','["10", "30", "3", "100"]'::jsonb,0,'3.048 / 0.3048 = 10.','original'),
('127.419.d.11.B',3,'A right angle measures:','["360 degrees", "90 degrees", "45 degrees", "180 degrees"]'::jsonb,1,'Right angles are 90 degrees.','original'),
('127.419.d.11.B',4,'One degree contains how many minutes of arc?','["360", "10", "60", "100"]'::jsonb,2,'1 degree = 60 minutes.','original'),
('127.419.d.11.C',3,'Excavation volume is often reported in cubic:','["hours", "minutes", "pounds", "yards"]'::jsonb,3,'Yards measure earthwork volume.','original'),
('127.419.d.11.C',4,'One cubic yard equals how many cubic feet?','["27", "3", "81", "9"]'::jsonb,0,'3 x 3 x 3 = 27.','original'),
('127.419.d.11.D',3,'One acre equals:','["4,000 square feet", "43,560 square feet", "435,600 square feet", "4,356 square feet"]'::jsonb,1,'Standard definition.','original'),
('127.419.d.11.D',4,'A hectare is a metric unit of area equal to how many square meters?','["100,000", "100", "10,000", "1,000"]'::jsonb,2,'1 ha = 100 m x 100 m.','original'),
('127.419.d.11.E',3,'To change 2 acres to square feet, multiply 2 by:','["4,356", "5,280", "3,560", "43,560"]'::jsonb,3,'2 x 43,560 = 87,120.','original'),
('127.419.d.11.E',4,'A tract measures 87,120 square feet. Its area in acres is:','["2", "4", "3", "1"]'::jsonb,0,'87,120 / 43,560 = 2.','original'),
('127.419.d.11.F',3,'A level run starts at a benchmark and ends 15 inches higher than where it began. In feet, the change in elevation is:','["-1.25 ft", "+1.25 ft", "0 ft", "+12.5 ft"]'::jsonb,1,'Change is the final minus the starting.','original'),
('127.419.d.11.F',4,'A surveyor reads backsight 5.20 ft and foresight 3.10 ft. The new point is higher than the old by:','["5.20 ft", "8.30 ft", "2.10 ft", "3.10 ft"]'::jsonb,2,'BS - FS = 2.10.','original'),
('127.419.d.11.G',3,'An industry-accepted method for measuring the horizontal distance between two points far apart over open ground is:','["pacing only", "eyeballing", "string by hand", "electronic distance measurement"]'::jsonb,3,'EDM is accurate over distance.','original'),
('127.419.d.11.G',4,'Surveyors accept GPS and EDM for long distances because both provide the:','["required accuracy", "lowest cost always", "fastest sound", "smallest instrument"]'::jsonb,0,'Accuracy requirements decide the method.','original'),
('127.419.d.11.H',3,'A tape reading differs from the EDM reading by 0.04 ft. The error expressed relative to a 400 ft line is:','["1 in 40", "1 in 10,000", "1 in 100", "1 in 1,000"]'::jsonb,1,'0.04 / 400 = 1/10,000.','original'),
('127.419.d.11.H',4,'A method whose error is 1 in 5,000 is less precise than one with an error of:','["1 in 1,000", "1 in 500", "1 in 20,000", "1 in 100"]'::jsonb,2,'Larger denominator is better precision.','original'),
('127.419.d.11.I',3,'Errors in survey data are classified as blunders, systematic errors, and:','["colored errors", "taxed errors", "mapped errors", "random errors"]'::jsonb,3,'Three classes of error.','original'),
('127.419.d.11.I',4,'A traverse angle is recorded as 62 degrees when the correct value is 26 degrees because the digits were swapped. This is a:','["blunder", "systematic error", "random error", "tolerance"]'::jsonb,0,'A transposition is a blunder.','original'),
('127.419.d.12.A',3,'Eratosthenes estimated the circumference of the Earth by comparing the lengths of shadows at two different:','["moons", "cities", "lakes", "seasons"]'::jsonb,1,'He used Syene and Alexandria.','original'),
('127.419.d.12.A',4,'Eratosthenes found that the angle of the shadow difference was about one fiftieth of a circle, so the Earth''s circumference was about 50 times the distance between:','["two stars", "two moons", "the two cities", "two oceans"]'::jsonb,2,'Proportion gave the size.','original'),
('127.419.d.12.B',3,'Surveyors once measured the Earth with chains and sextants, while modern surveyors use satellites, which has greatly improved:','["seasons", "price of land", "weight", "precision"]'::jsonb,3,'Methods improved over time.','original'),
('127.419.d.12.B',4,'The development of the theodolite, then the electronic distance meter, then GPS each increased the speed and accuracy of measuring the:','["size and shape of the Earth", "names of states", "number of surveyors", "price of maps"]'::jsonb,0,'Technology advanced geodesy.','original'),
('127.419.d.12.C',3,'Surveyors laid out the line and grade for large works such as canals, railroads, and:','["songs", "dams", "stories", "menus"]'::jsonb,1,'Surveying supports big projects.','original'),
('127.419.d.12.C',4,'The Panama Canal depended on accurate surveying to control the water levels and the locations of its:','["teams", "colors", "locks", "maps"]'::jsonb,2,'Elevations determined lock design.','original'),
('127.419.d.13.A',3,'Surveyors use legal definitions such as "easement," "encroachment," and "boundary" to describe the rights tied to:','["movies", "fashion", "music", "real property"]'::jsonb,3,'Legal terms define land rights.','original'),
('127.419.d.13.A',4,'The legal term for a structure that extends across a property line onto a neighbor''s land is an:','["encroachment", "monument", "covenant", "easement"]'::jsonb,0,'Encroachments cross boundaries.','original'),
('127.419.d.13.B',3,'The Texas rules for professional land surveyors require them to hold paramount the public''s:','["comfort", "safety and welfare", "entertainment", "opinion"]'::jsonb,1,'Safety comes first.','original'),
('127.419.d.13.B',4,'A licensed surveyor asked by a client to alter a boundary measurement to favor the client should:','["charge more", "agree quietly", "refuse and report accurately", "hide the field notes"]'::jsonb,2,'Honesty is required.','original'),
('127.418.d.9.L',4,'A drawing of the front face of a house, flattened without perspective, is called an:','["site survey", "roof detail", "plan", "elevation"]'::jsonb,3,'Elevations show the vertical faces of a building.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
